// Light tags: full = full sun, part = part shade, shade = full shade. Plants without a sun list get one from their light text.
window.PLANTS.forEach(p => {
  if (!p.sun) { const l = p.light.toLowerCase(); p.sun = []; if (/\bsun\b/.test(l)) p.sun.push("full"); if (/part|light shade/.test(l)) p.sun.push("part"); if (/full shade/.test(l)) p.sun.push("shade"); }
  if (!p.toxic) p.toxic = null;
});
// "Toxic to people, dogs and cats" style label, or "" for plants believed non-toxic
window.toxLabel = p => { if (!p.toxic || !p.toxic.length) return ""; const t = p.toxic.slice(); const last = t.pop(); return "Toxic to " + (t.length ? t.join(", ") + " and " + last : last); };

// Photo focus (0..1) used when cropping the stored photo to 4:3; default is center.
window.PHOTO_FOCUS = {
  sedge: [.5, .5], foam: [.5, .45], phlox: [.45, .5], jacobs: [.5, .45], bluebells: [.55, .45], fern: [.55, .5],
  geranium: [.48, .5], goldenrod: [.55, .45], aster: [.5, .5], turtle: [.45, .4], coral: [.5, .5], forestgrass: [.5, .5],
  brunnera: [.5, .45], rozanne: [.4, .45], astilbe: [.5, .3]
};
